from pathlib import Path

Path("ui_styles.py").write_text('"""\nShared professional styling for the Baseball Apps Hub.\nNeutral, team-flexible theme system for all app pages.\n"""\n\nimport streamlit as st\n\n\nTHEMES = {\n    "Neutral Baseball": {\n        "primary": "#0f172a",\n        "secondary": "#2563eb",\n        "accent": "#f97316",\n        "sidebar_1": "#0f172a",\n        "sidebar_2": "#1e293b",\n    },\n    "Navy / Red": {\n        "primary": "#0b1f3a",\n        "secondary": "#2563eb",\n        "accent": "#dc2626",\n        "sidebar_1": "#071525",\n        "sidebar_2": "#102a4c",\n    },\n    "Navy / Gold": {\n        "primary": "#111827",\n        "secondary": "#1d4ed8",\n        "accent": "#d97706",\n        "sidebar_1": "#111827",\n        "sidebar_2": "#263244",\n    },\n    "Green / White": {\n        "primary": "#064e3b",\n        "secondary": "#059669",\n        "accent": "#84cc16",\n        "sidebar_1": "#052e24",\n        "sidebar_2": "#064e3b",\n    },\n    "Black / Orange": {\n        "primary": "#111827",\n        "secondary": "#ea580c",\n        "accent": "#f97316",\n        "sidebar_1": "#111111",\n        "sidebar_2": "#1f2937",\n    },\n}\n\n\ndef theme_picker(default="Neutral Baseball"):\n    with st.sidebar:\n        st.markdown(\'<div class="sidebar-section-title">Theme</div>\', unsafe_allow_html=True)\n        choice = st.selectbox(\n            "Brand Theme",\n            list(THEMES.keys()),\n            index=list(THEMES.keys()).index(default) if default in THEMES else 0,\n            key="hub_brand_theme",\n        )\n    return THEMES[choice]\n\n\ndef apply_page_style(theme=None):\n    if theme is None:\n        theme = THEMES["Neutral Baseball"]\n\n    primary = theme["primary"]\n    secondary = theme["secondary"]\n    sidebar_1 = theme["sidebar_1"]\n    sidebar_2 = theme["sidebar_2"]\n\n    st.markdown(f"""\n    <style>\n        .stApp {{\n            background:\n                radial-gradient(circle at top right, rgba(37,99,235,.10), transparent 30%),\n                linear-gradient(135deg, #f8fafc 0%, #eef2f7 100%);\n        }}\n\n        .block-container {{\n            padding-top: 2.4rem;\n            padding-bottom: 3rem;\n            max-width: 1320px;\n        }}\n\n        section[data-testid="stSidebar"] {{\n            background: linear-gradient(180deg, {sidebar_1} 0%, {sidebar_2} 100%) !important;\n            border-right: 1px solid rgba(255,255,255,.08);\n        }}\n\n        section[data-testid="stSidebar"] label,\n        section[data-testid="stSidebar"] p,\n        section[data-testid="stSidebar"] span,\n        section[data-testid="stSidebar"] h1,\n        section[data-testid="stSidebar"] h2,\n        section[data-testid="stSidebar"] h3 {{\n            color: #f8fafc !important;\n        }}\n\n        section[data-testid="stSidebar"] .sidebar-section-title {{\n            color: #cbd5e1 !important;\n            font-size: .78rem;\n            font-weight: 900;\n            text-transform: uppercase;\n            letter-spacing: .09em;\n            margin: 1.25rem 0 .35rem 0;\n        }}\n\n        section[data-testid="stSidebar"] input,\n        section[data-testid="stSidebar"] textarea {{\n            color: #0f172a !important;\n            background: #ffffff !important;\n        }}\n\n        section[data-testid="stSidebar"] [data-baseweb="select"] > div {{\n            background-color: #ffffff !important;\n            color: #0f172a !important;\n            border-radius: 14px !important;\n        }}\n\n        section[data-testid="stSidebar"] [data-baseweb="select"] * {{\n            color: #0f172a !important;\n        }}\n\n        section[data-testid="stSidebar"] div[data-testid="stFileUploader"] {{\n            background: rgba(255,255,255,.96) !important;\n            border-radius: 18px !important;\n            box-shadow: 0 10px 25px rgba(0,0,0,.18);\n        }}\n\n        section[data-testid="stSidebar"] div[data-testid="stFileUploader"] * {{\n            color: #0f172a !important;\n            opacity: 1 !important;\n        }}\n\n        h1 {{\n            color: #0f172a !important;\n            font-weight: 950 !important;\n            letter-spacing: -1.3px;\n        }}\n\n        h2, h3 {{\n            color: #0f172a !important;\n            font-weight: 850 !important;\n        }}\n\n        div[data-testid="stFileUploader"] {{\n            background: #ffffff !important;\n            border: 1px solid #e5e7eb !important;\n            border-radius: 18px !important;\n            padding: 16px !important;\n            box-shadow: 0 8px 22px rgba(15,23,42,.08);\n        }}\n\n        div[data-testid="stFileUploader"] * {{\n            color: #0f172a !important;\n            opacity: 1 !important;\n        }}\n\n        div[data-testid="stAlert"] {{\n            border-radius: 16px !important;\n            border: none !important;\n            box-shadow: 0 6px 16px rgba(15,23,42,.08);\n        }}\n\n        .stButton > button,\n        .stDownloadButton > button {{\n            border-radius: 12px !important;\n            border: none !important;\n            background: linear-gradient(135deg, {primary}, {secondary}) !important;\n            color: white !important;\n            font-weight: 850 !important;\n            padding: .65rem 1.1rem !important;\n            box-shadow: 0 8px 18px rgba(37,99,235,.22);\n            transition: all .15s ease;\n        }}\n\n        .stButton > button:hover,\n        .stDownloadButton > button:hover {{\n            transform: translateY(-1px);\n            box-shadow: 0 12px 24px rgba(37,99,235,.30);\n        }}\n\n        div[data-testid="stNumberInput"] input {{\n            color: #0f172a !important;\n            background: #ffffff !important;\n            font-weight: 800 !important;\n        }}\n\n        div[data-testid="stNumberInput"] button {{\n            color: #0f172a !important;\n            background: #ffffff !important;\n            opacity: 1 !important;\n            border-left: 1px solid #e5e7eb !important;\n        }}\n\n        div[data-testid="stNumberInput"] button svg,\n        div[data-testid="stNumberInput"] button svg path {{\n            color: #0f172a !important;\n            fill: #0f172a !important;\n            stroke: #0f172a !important;\n            opacity: 1 !important;\n        }}\n\n        div[data-testid="stDataFrame"],\n        div[data-testid="stTable"] {{\n            border-radius: 18px !important;\n            overflow: hidden;\n            box-shadow: 0 8px 22px rgba(15,23,42,.08);\n            border: 1px solid #e5e7eb;\n        }}\n\n        .app-header {{\n            padding: 32px 38px;\n            border-radius: 26px;\n            background:\n                linear-gradient(135deg, rgba(15,23,42,.96), rgba(37,99,235,.86)),\n                radial-gradient(circle at top right, rgba(249,115,22,.32), transparent 35%);\n            color: white;\n            margin-bottom: 28px;\n            box-shadow: 0 16px 38px rgba(15,23,42,.22);\n            position: relative;\n            overflow: hidden;\n        }}\n\n        .app-header h1 {{\n            color: white !important;\n            margin: 0 0 8px 0;\n            font-size: 44px !important;\n            font-weight: 950 !important;\n            position: relative;\n            z-index: 1;\n        }}\n\n        .app-header p {{\n            color: #dbeafe !important;\n            font-size: 18px;\n            margin: 0;\n            position: relative;\n            z-index: 1;\n        }}\n\n        .soft-card {{\n            background: white;\n            border: 1px solid #e5e7eb;\n            border-radius: 22px;\n            padding: 22px;\n            box-shadow: 0 10px 26px rgba(15,23,42,.08);\n        }}\n    </style>\n    """, unsafe_allow_html=True)\n\n\ndef app_header(title, subtitle="Baseball operations tool"):\n    st.markdown(\n        f"""\n        <div class="app-header">\n            <h1>{title}</h1>\n            <p>{subtitle}</p>\n        </div>\n        """,\n        unsafe_allow_html=True,\n    )\n')
Path("Home.py").write_text('import streamlit as st\nfrom pathlib import Path\n\nst.set_page_config(\n    page_title="Baseball Operations Portal",\n    page_icon="⚾",\n    layout="wide",\n)\n\ntry:\n    from ui_styles import apply_page_style, theme_picker\n    theme = theme_picker()\n    apply_page_style(theme)\nexcept Exception:\n    theme = None\n\nPAGES_DIR = Path("pages")\n\nAPP_LIBRARY = [\n    {"title": "LIDOM Projection", "category": "League Tools", "icon": "📈", "desc": "Project league performance and translate hitter profiles across winter ball environments.", "keywords": "lidom projection winter league hitter grader"},\n    {"title": "Lineup Optimization", "category": "Game Planning", "icon": "🧢", "desc": "Build lineup combinations based on offensive value, role, handedness, and team constraints.", "keywords": "lineup optimization batting order"},\n    {"title": "Pitch Characteristics", "category": "Player Analysis", "icon": "⚾", "desc": "Compare pitch traits, movement, velocity, similarity scores, and player profiles.", "keywords": "pitch characteristics similarity pitcher movement velocity"},\n    {"title": "Leaderboard Report", "category": "Reports", "icon": "🏆", "desc": "Generate clean player leaderboards across hitting, pitching, defense, and baserunning.", "keywords": "leaderboard report hitting pitching defense baserunning"},\n    {"title": "Hitter vs Pitcher Matchup", "category": "Game Planning", "icon": "⚔️", "desc": "Evaluate historical matchup performance between hitters and pitchers.", "keywords": "hitter pitcher matchup batter pitcher"},\n    {"title": "LIDOM Team Leaderboard", "category": "League Tools", "icon": "📊", "desc": "Compare team rankings, strengths, weaknesses, and advanced league-level metrics.", "keywords": "team leaderboard lidom rankings advanced metrics"},\n    {"title": "Pregame Visual Report", "category": "Reports", "icon": "📋", "desc": "Create opponent reports, visuals, summaries, and game-planning material.", "keywords": "pregame report visual opponent scouting"},\n]\n\ndef available_pages():\n    if not PAGES_DIR.exists():\n        return {}\n    files = list(PAGES_DIR.glob("*.py"))\n    mapping = {}\n    for file in files:\n        normalized = file.stem.lower().replace("_", " ").replace("-", " ")\n        for app in APP_LIBRARY:\n            words = app["title"].lower().split()\n            score = sum(1 for word in words if word in normalized)\n            if score >= max(1, len(words) // 2):\n                mapping[app["title"]] = str(file)\n    return mapping\n\npage_map = available_pages()\n\nst.markdown("""\n<style>\n.portal-hero {\n    padding: 42px 46px;\n    border-radius: 30px;\n    background:\n        linear-gradient(135deg, rgba(15,23,42,.96), rgba(37,99,235,.86)),\n        radial-gradient(circle at top right, rgba(249,115,22,.38), transparent 35%);\n    color: white;\n    box-shadow: 0 18px 42px rgba(15,23,42,.24);\n    margin-bottom: 28px;\n    overflow: hidden;\n    position: relative;\n}\n.portal-hero::after {\n    content: "";\n    position: absolute;\n    right: -90px;\n    top: -80px;\n    width: 260px;\n    height: 260px;\n    border-radius: 999px;\n    background: rgba(255,255,255,.10);\n}\n.hero-kicker {\n    font-size: .85rem;\n    font-weight: 900;\n    letter-spacing: .12em;\n    text-transform: uppercase;\n    color: #bfdbfe;\n    margin-bottom: 10px;\n    position: relative;\n    z-index: 1;\n}\n.portal-hero h1 {\n    font-size: 3.35rem !important;\n    line-height: 1.02;\n    margin: 0 0 12px 0;\n    color: white !important;\n    position: relative;\n    z-index: 1;\n}\n.portal-hero p {\n    font-size: 1.15rem;\n    color: #e0f2fe;\n    max-width: 760px;\n    margin: 0;\n    position: relative;\n    z-index: 1;\n}\n.metric-strip {\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 14px;\n    margin: 22px 0 30px 0;\n}\n.metric-box {\n    background: rgba(255,255,255,.92);\n    border: 1px solid #e5e7eb;\n    border-radius: 18px;\n    padding: 18px;\n    box-shadow: 0 9px 24px rgba(15,23,42,.08);\n}\n.metric-label {\n    color: #64748b;\n    font-weight: 900;\n    text-transform: uppercase;\n    font-size: .76rem;\n    letter-spacing: .06em;\n}\n.metric-value {\n    color: #0f172a;\n    font-size: 1.55rem;\n    font-weight: 950;\n    margin-top: 4px;\n}\n.section-title {\n    margin-top: 10px;\n    font-size: 1.45rem;\n    font-weight: 950;\n    color: #0f172a;\n}\n.section-subtitle {\n    color: #64748b;\n    margin-bottom: 18px;\n}\n.app-card {\n    background: white;\n    border: 1px solid #e5e7eb;\n    border-radius: 24px;\n    padding: 24px;\n    min-height: 238px;\n    box-shadow: 0 9px 24px rgba(15,23,42,.08);\n    transition: all .16s ease;\n    border-top: 5px solid #2563eb;\n}\n.app-card:hover {\n    transform: translateY(-3px);\n    box-shadow: 0 14px 34px rgba(15,23,42,.14);\n}\n.app-category {\n    font-size: .75rem;\n    color: #64748b;\n    font-weight: 900;\n    letter-spacing: .08em;\n    text-transform: uppercase;\n}\n.app-icon {\n    width: 58px;\n    height: 58px;\n    border-radius: 18px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    background: linear-gradient(135deg, #eff6ff, #dbeafe);\n    font-size: 2rem;\n    margin: 13px 0 14px 0;\n}\n.app-title {\n    color: #0f172a;\n    font-size: 1.18rem;\n    font-weight: 950;\n    margin-bottom: 8px;\n}\n.app-desc {\n    color: #475569;\n    font-size: .95rem;\n    line-height: 1.45;\n    min-height: 70px;\n}\n.workflow {\n    background: white;\n    border: 1px solid #e5e7eb;\n    border-radius: 24px;\n    padding: 24px;\n    box-shadow: 0 9px 24px rgba(15,23,42,.08);\n    margin-top: 30px;\n}\n.workflow-step {\n    padding: 13px 15px;\n    border-left: 4px solid #2563eb;\n    background: #f8fafc;\n    border-radius: 12px;\n    margin-bottom: 10px;\n    color: #0f172a;\n    font-weight: 750;\n}\n.footer-line {\n    text-align: center;\n    color: #64748b;\n    margin-top: 38px;\n    padding-top: 18px;\n    border-top: 1px solid #e5e7eb;\n    font-size: .92rem;\n}\n</style>\n""", unsafe_allow_html=True)\n\nst.markdown("""\n<div class="portal-hero">\n    <div class="hero-kicker">Baseball Operations Platform</div>\n    <h1>Baseball Apps Hub</h1>\n    <p>One central portal for reports, projections, matchups, leaderboards, player analysis, and game-planning workflows.</p>\n</div>\n""", unsafe_allow_html=True)\n\ntotal_apps = len(APP_LIBRARY)\navailable = len(page_map)\ncategories = len(set(app["category"] for app in APP_LIBRARY))\n\nst.markdown(f"""\n<div class="metric-strip">\n    <div class="metric-box"><div class="metric-label">Available Apps</div><div class="metric-value">{available}/{total_apps}</div></div>\n    <div class="metric-box"><div class="metric-label">Categories</div><div class="metric-value">{categories}</div></div>\n    <div class="metric-box"><div class="metric-label">Focus</div><div class="metric-value">PD / Scouting</div></div>\n    <div class="metric-box"><div class="metric-label">Workflow</div><div class="metric-value">Reports</div></div>\n</div>\n""", unsafe_allow_html=True)\n\nsearch = st.text_input("Search apps", placeholder="Search reports, projections, matchups, pitching, leaderboard...", label_visibility="collapsed")\ncategory_options = ["All"] + sorted(set(app["category"] for app in APP_LIBRARY))\ncategory = st.selectbox("Filter by category", category_options, label_visibility="collapsed")\n\nfiltered = []\nfor app in APP_LIBRARY:\n    haystack = f\'{app["title"]} {app["category"]} {app["desc"]} {app["keywords"]}\'.lower()\n    if search and search.lower() not in haystack:\n        continue\n    if category != "All" and app["category"] != category:\n        continue\n    filtered.append(app)\n\nst.markdown("""\n<div class="section-title">App Library</div>\n<div class="section-subtitle">Choose a tool below or use the sidebar navigation.</div>\n""", unsafe_allow_html=True)\n\nfor row_start in range(0, len(filtered), 3):\n    cols = st.columns(3)\n    for col, app in zip(cols, filtered[row_start:row_start + 3]):\n        page = page_map.get(app["title"])\n        with col:\n            st.markdown(f"""\n            <div class="app-card">\n                <div class="app-category">{app["category"]}</div>\n                <div class="app-icon">{app["icon"]}</div>\n                <div class="app-title">{app["title"]}</div>\n                <div class="app-desc">{app["desc"]}</div>\n            </div>\n            """, unsafe_allow_html=True)\n            if page:\n                st.page_link(page, label=f"Launch {app[\'title\']}", icon="➡️")\n            else:\n                st.caption("Page file not detected yet.")\n            st.write("")\n\nst.markdown("""\n<div class="workflow">\n    <div class="section-title" style="margin-top:0;">Recommended Workflow</div>\n    <div class="section-subtitle">A simple way to move from preparation to reporting.</div>\n    <div class="workflow-step">1. Upload or prepare source CSVs in the app that matches your task.</div>\n    <div class="workflow-step">2. Review filters, thresholds, and league/team context.</div>\n    <div class="workflow-step">3. Generate tables, visuals, summaries, or PDFs.</div>\n    <div class="workflow-step">4. Share the output with coaches, analysts, scouts, or decision-makers.</div>\n</div>\n""", unsafe_allow_html=True)\n\nst.markdown("""\n<div class="footer-line">\n    Baseball Operations Portal • Team-neutral analytics, reports, and game-planning tools\n</div>\n""", unsafe_allow_html=True)\n')

print("Updated Home.py and ui_styles.py with portal theme v3.")
